import React from 'react';
import './FaceRecognition.css';

const expressionEmoji = {
  happy: '😊',
  sad: '😢',
  angry: '😠',
  fearful: '😨',
  disgusted: '🤢',
  surprised: '😮',
  neutral: '😐'
};

const FaceRecognition = ({ detections, imageUrl, onImageLoaded }) => {
  return (
    <div className='fr-container'>
      {imageUrl && (
        <div className='fr-image-wrap'>
          <img
            id='inputimage'
            className='fr-image'
            alt='detected face'
            src={imageUrl}
            crossOrigin='anonymous'
            onLoad={onImageLoaded}
          />
          {detections.map((face, i) => (
            <div key={i}>
              {/* Bounding Box */}
              <div
                className='fr-bounding-box'
                style={{
                  top: face.box.topRow,
                  left: face.box.leftCol,
                  width: face.box.width,
                  height: face.box.height
                }}
              >
                <div className='fr-corner fr-corner-tl'></div>
                <div className='fr-corner fr-corner-tr'></div>
                <div className='fr-corner fr-corner-bl'></div>
                <div className='fr-corner fr-corner-br'></div>
              </div>

              {/* Face Info Card */}
              <div
                className='fr-info-card'
                style={{
                  top: face.box.topRow + face.box.height + 8,
                  left: face.box.leftCol,
                  minWidth: Math.max(face.box.width, 120)
                }}
              >
                <div className='fr-info-row'>
                  <span className='fr-info-emoji'>{expressionEmoji[face.expression] || '😐'}</span>
                  <span className='fr-info-label'>{face.expression}</span>
                  <span className='fr-info-value'>{face.expressionScore}%</span>
                </div>
                <div className='fr-info-row'>
                  <span className='fr-info-emoji'>🎂</span>
                  <span className='fr-info-label'>Age</span>
                  <span className='fr-info-value'>~{face.age}</span>
                </div>
                <div className='fr-info-row'>
                  <span className='fr-info-emoji'>{face.gender === 'male' ? '♂️' : '♀️'}</span>
                  <span className='fr-info-label'>{face.gender}</span>
                  <span className='fr-info-value'>{face.genderProbability}%</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default FaceRecognition;
